describe('Export Records to CSV', () => {
    beforeEach(() => {
        cy.visit('/records'); // Replace with the actual URL of the records page
    });

    it('should successfully export records to CSV', () => {
        cy.get('button#export-csv').click(); // Replace with the actual selector for the export button
        cy.wait(2000); // Wait for the export to complete, adjust as necessary
        cy.readFile('cypress/downloads/records.csv').should('exist'); // Adjust the path as necessary
        cy.readFile('cypress/downloads/records.csv').should('contain', 'Header1,Header2,Header3'); // Check for expected headers
    });

    it('should handle export failure gracefully', () => {
        cy.intercept('GET', '/api/records/export', { statusCode: 500 }).as('exportFailure'); // Mocking a failure response
        cy.get('button#export-csv').click();
        cy.wait('@exportFailure');
        cy.get('.error-message').should('be.visible').and('contain', 'Failed to export records'); // Adjust the selector and message as necessary
    });
});
